# Lesson program for compiling specifications into explicit decision boundaries.
# Read: phases/14-agent-engineering/51-write-specifications-that-preserve-judgment/docs/en.md
# Reference: Zave and Jackson, Four Dark Corners of Requirements Engineering, 1997.
# Reference: Gotel and Finkelstein, Requirements Traceability, IEEE ICRE 1994.
# Run this file to generate outputs/executable-specification.json.
from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path


@dataclass(frozen=True)
class Decision:
    question: str
    mode: str
    rationale: str


@dataclass
class Specification:
    outcome: str
    invariants: list[str]
    examples: list[str]
    non_goals: list[str]
    decisions: list[Decision]
    proof: list[str]


VALID_MODES = {"locked", "bounded", "delegated"}


def validate(specification: Specification) -> list[str]:
    issues: list[str] = []
    for field_name in ("outcome", "invariants", "examples", "non_goals", "decisions", "proof"):
        if not getattr(specification, field_name):
            issues.append(f"{field_name} is empty")
    for decision in specification.decisions:
        if decision.mode not in VALID_MODES:
            issues.append(f"invalid decision mode: {decision.mode}")
        if decision.mode != "delegated" and not decision.rationale.strip():
            issues.append(f"constrained decision lacks rationale: {decision.question}")
    return issues


def compile_contract(specification: Specification) -> dict:
    issues = validate(specification)
    return {
        "status": "executable" if not issues else "incomplete",
        "issues": issues,
        "contract": asdict(specification),
        "agent_may_decide": [item.question for item in specification.decisions if item.mode == "delegated"],
        "bounded_decisions": [
            {"question": item.question, "boundary": item.rationale}
            for item in specification.decisions
            if item.mode == "bounded"
        ],
        "human_checkpoint": [item.question for item in specification.decisions if item.mode == "locked"],
    }


def example() -> Specification:
    return Specification(
        outcome="Identify the affected service from an incident alert in under two minutes",
        invariants=["diagnosis is read-only", "every source is included in the audit record"],
        examples=["an alert with a deployment id resolves to its service owner"],
        non_goals=["automatic remediation", "changing alert routing"],
        decisions=[
            Decision("Which read-only data source should be queried first?", "delegated", ""),
            Decision("May the system write to production?", "locked", "Production authority stays with the incident commander"),
            Decision("How many sources may be queried?", "bounded", "Stop after five sources or two minutes"),
        ],
        proof=["ten recorded incident replays", "zero production writes"],
    )


def main() -> None:
    output = Path(__file__).resolve().parents[1] / "outputs" / "executable-specification.json"
    output.write_text(json.dumps(compile_contract(example()), indent=2) + "\n", encoding="utf-8")
    print(output.read_text(encoding="utf-8"))


if __name__ == "__main__":
    main()

"""Role specialization: planner, executor, critic, verifier.

Builds a small Python function. Critic (LLM-simulated) and verifier (code)
together catch bugs that either alone would miss.

Run twice: once with correct executor output, once with off-spec output.
"""
from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Spec:
    task_name: str
    signature: str
    description: str
    tests: list[tuple[tuple, int]]


@dataclass
class Artifact:
    code: str


@dataclass
class CriticReport:
    approved: bool
    notes: list[str] = field(default_factory=list)


@dataclass
class VerifierReport:
    passed: bool
    failures: list[str] = field(default_factory=list)


def planner(user_wish: str) -> Spec:
    """Produces a structured spec from a high-level wish."""
    return Spec(
        task_name="add_two",
        signature="add_two(a: int, b: int) -> int",
        description=user_wish,
        tests=[((1, 2), 3), ((10, 20), 30), ((-5, 5), 0)],
    )


def executor_correct(spec: Spec) -> Artifact:
    return Artifact(code="def add_two(a, b):\n    return a + b\n")


def executor_buggy(spec: Spec) -> Artifact:
    return Artifact(code="def add_two(a, b):\n    return a * b\n")


def critic(spec: Spec, art: Artifact) -> CriticReport:
    """LLM-style review. Pattern-matches against common issues but can be fooled
    by plausible-looking code that is semantically wrong."""
    notes: list[str] = []
    if "def" not in art.code:
        notes.append("missing def statement")
    if "return" not in art.code:
        notes.append("missing return")
    if spec.task_name not in art.code:
        notes.append(f"function name does not match spec '{spec.task_name}'")
    approved = not notes
    return CriticReport(approved=approved, notes=notes)


def verifier(spec: Spec, art: Artifact) -> VerifierReport:
    """Run the code in a sandbox namespace and execute the tests. Deterministic."""
    ns: dict = {}
    try:
        exec(art.code, ns, ns)
    except Exception as e:
        return VerifierReport(passed=False, failures=[f"exec error: {e}"])
    fn = ns.get(spec.task_name)
    if not callable(fn):
        return VerifierReport(passed=False, failures=[f"no callable '{spec.task_name}' produced"])
    failures: list[str] = []
    for args, expected in spec.tests:
        try:
            got = fn(*args)
        except Exception as e:
            failures.append(f"call {args} raised {e}")
            continue
        if got != expected:
            failures.append(f"call {args}: expected {expected}, got {got}")
    return VerifierReport(passed=not failures, failures=failures)


def run_pipeline(user_wish: str, executor, label: str) -> None:
    print(f"\n=== {label} ===")
    spec = planner(user_wish)
    print(f"  [planner] spec: {spec.signature} with {len(spec.tests)} tests")
    art = executor(spec)
    print(f"  [executor] produced:\n    {art.code.replace(chr(10), chr(10)+'    ')}")
    crep = critic(spec, art)
    print(f"  [critic] approved={crep.approved}, notes={crep.notes}")
    vrep = verifier(spec, art)
    print(f"  [verifier] passed={vrep.passed}, failures={vrep.failures}")
    if crep.approved and vrep.passed:
        print("  RESULT: ship it.")
    elif not vrep.passed:
        print("  RESULT: verifier blocked ship (deterministic catch).")
    elif not crep.approved:
        print("  RESULT: critic blocked ship (subjective catch).")


def main() -> None:
    print("Role specialization pipeline — planner, executor, critic, verifier")
    print("-" * 70)

    run_pipeline(
        "A function that returns the sum of two integers.",
        executor_correct,
        "Correct executor output",
    )

    run_pipeline(
        "A function that returns the sum of two integers.",
        executor_buggy,
        "Buggy executor output (looks plausible; fails runtime)",
    )

    print("\nKey insight: the critic passes the buggy code because it looks fine.")
    print("Only the verifier -- deterministic test execution -- catches the semantic bug.")
    print("All-LLM pipelines (no verifier) would ship the bug. Classic MAST failure mode.")


if __name__ == "__main__":
    main()

